const fs = require('fs');
const item = $input.first().json;

let prompt = fs.readFileSync('/prompts/categorize.md', 'utf8');
prompt = prompt
  .replace('{{title}}', item.title || '')
  .replace('{{summary}}', item.summary || '')
  .replace('{{topics}}', (item.topics || []).join(', '))
  .replace('{{source}}', item.source_name || '');

return [{ json: { ...item, prompt } }];

const item = $input.first().json;
const articleId = $('Get Articles').first().json.id;
let result;
try { result = JSON.parse(item.choices[0].message.content); } catch(e) { result = { category: 'other', confidence: 0.5 }; }
return [{ json: { article_id: articleId, ...result } }];
